CREATE TABLE users (
    id                  BIGINT PRIMARY KEY AUTO_INCREMENT,
    username            VARCHAR(50) UNIQUE NOT NULL,
    email               VARCHAR(100) UNIQUE NOT NULL,
    password_hash       VARCHAR(255) NULL,
    google_sub          VARCHAR(255) NULL,
    role                ENUM('admin','student') NOT NULL DEFAULT 'student',
    premium_plan        ENUM('none','1m','3m') NOT NULL DEFAULT 'none',
    premium_until       DATETIME DEFAULT NULL,
    current_session_id  VARCHAR(64) DEFAULT NULL,
    session_last_seen_at DATETIME DEFAULT NULL,
    full_name           VARCHAR(100),
    avatar_url          VARCHAR(255) DEFAULT NULL,
    is_active           BOOLEAN NOT NULL DEFAULT TRUE,
    total_score         DECIMAL(12,2) DEFAULT 0.00,
    total_quizzes       INT DEFAULT 0,
    total_correct       INT DEFAULT 0,
    total_questions     INT DEFAULT 0,
    average_percentage  DECIMAL(5,2) DEFAULT 0.00,
    last_login_at       DATETIME DEFAULT NULL,
    created_at          DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at          DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_active_score (is_active, total_score DESC),
    INDEX idx_email (email),
    INDEX idx_current_session (current_session_id),
    INDEX idx_premium_until (premium_until),
    UNIQUE KEY uq_users_google_sub (google_sub),
    CONSTRAINT chk_users_password_or_google CHECK (password_hash IS NOT NULL OR google_sub IS NOT NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Nguoi dung';

CREATE TABLE password_reset_tokens (
    id           BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id      BIGINT NOT NULL,
    token_hash   CHAR(64) NOT NULL,
    expires_at   DATETIME NOT NULL,
    used_at      DATETIME NULL,
    created_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    INDEX idx_reset_lookup (token_hash, expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Token dat lai mat khau (hash SHA256)';

CREATE TABLE premium_payment_requests (
    id                  BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id             BIGINT NOT NULL,
    plan_code           ENUM('1m','3m') NOT NULL,
    payer_note          TEXT,
    bill_storage_path   VARCHAR(500) NOT NULL,
    bill_cdn_url        VARCHAR(1000) NULL,
    status              ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',
    admin_note          VARCHAR(500) NULL,
    reviewed_at         DATETIME NULL,
    reviewed_by_id      BIGINT NULL,
    created_at          DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (reviewed_by_id) REFERENCES users(id) ON DELETE SET NULL,
    INDEX idx_status_created (status, created_at),
    INDEX idx_user_created (user_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Yeu cau dang ky Premium (CK + bill)';

