(137, 28, 2, 1.00, 'Người đi bộ đang qua vạch zebra, người lái phải làm gì?', 'Peatones en paso de cebra: ¿acción del conductor?', 'Pedestrians on zebra crossing — driver must?', 'Nhường đường, dừng nếu cần.', 'Ceder el paso; detenerse si hace falta.', 'Yield; stop if needed.', NULL),
(138, 28, 3, 1.00, 'Điện thoại cầm tay khi lái xe ở TBN?', '¿Móvil en mano conduciendo en España?', 'Handheld phone while driving in Spain?', 'Cấm; chỉ hands-free đúng quy định.', 'Prohibido; manos libres autorizado.', 'Banned; hands-free per rules only.', NULL),
(139, 28, 4, 1.00, 'Khoảng cách tối thiểu với xe trước thường được nhắc bằng quy tắc nào?', '¿Regla mnemotécnica de distancia?', 'Common mnemonic for following distance?', 'Quy tắc 2 giây (hoặc 3 giây khi trời mưa).', 'Regla de los 2 segundos (3 si lluvia).', 'Two-second rule (three if wet).', NULL),
(140, 28, 5, 1.00, 'Trên đường đô thị, tốc độ tối đa cho ô tô con (trừ khi biển báo khác) thường là bao nhiêu?', 'En vía urbana, ¿cuál es la velocidad máxima genérica para turismos si no indica otra señal?', 'In urban areas, what is the usual max speed for cars unless signed otherwise?', 'Theo quy định chung TBN (trừ khi có biển), thường 50 km/h trong đô thị.', 'En España suele ser 50 km/h en travesías urbanas salvo señalización.', 'In Spain typically 50 km/h in built-up areas unless otherwise posted.', NULL),
(141, 29, 1, 1.00, 'Tín hiệu đèn đỏ tại giao lộ có nghĩa gì?', '¿Qué significa el semáforo en rojo en un cruce?', 'What does a red traffic light at a junction mean?', 'Dừng trước vạch dừng; không được đi (trừ quy định rẽ phải nơi cho phép).', 'Detenerse; no pasar salvo giro autorizado donde aplique.', 'Stop; do not proceed unless permitted turn applies.', NULL),
(142, 29, 2, 1.00, 'Khoảng cách an toàn phụ thuộc chủ yếu vào điều gì?', '¿En qué depende principalmente la distancia de seguridad?', 'What does safe following distance mainly depend on?', 'Tốc độ, điều kiện đường, mưa và phản ứng người lái.', 'Velocidad, adherencia, lluvia y tiempo de reacción.', 'Speed, grip, weather, and reaction time.', NULL),
(143, 29, 3, 1.00, 'Biển hình tròn viền đỏ nền trắng (không có gạch chéo) thường là nhóm gì?', 'Señal circular borde rojo fondo blanco sin banda: ¿grupo?', 'Circular red border white face — which sign group?', 'Thường là biển cấm (prohibición).', 'Prohibición.', 'Prohibition.', NULL),
(144, 29, 4, 1.00, 'Người đi bộ đang qua vạch zebra, người lái phải làm gì?', 'Peatones en paso de cebra: ¿acción del conductor?', 'Pedestrians on zebra crossing — driver must?', 'Nhường đường, dừng nếu cần.', 'Ceder el paso; detenerse si hace falta.', 'Yield; stop if needed.', NULL),
(145, 29, 5, 1.00, 'Điện thoại cầm tay khi lái xe ở TBN?', '¿Móvil en mano conduciendo en España?', 'Handheld phone while driving in Spain?', 'Cấm; chỉ hands-free đúng quy định.', 'Prohibido; manos libres autorizado.', 'Banned; hands-free per rules only.', NULL),
(146, 30, 1, 1.00, 'Trên đường đô thị, tốc độ tối đa cho ô tô con (trừ khi biển báo khác) thường là bao nhiêu?', 'En vía urbana, ¿cuál es la velocidad máxima genérica para turismos si no indica otra señal?', 'In urban areas, what is the usual max speed for cars unless signed otherwise?', 'Theo quy định chung TBN (trừ khi có biển), thường 50 km/h trong đô thị.', 'En España suele ser 50 km/h en travesías urbanas salvo señalización.', 'In Spain typically 50 km/h in built-up areas unless otherwise posted.', NULL),
(147, 30, 2, 1.00, 'Khi nào được phép vượt xe bên phải?', '¿Cuándo está permitido adelantar por la derecha?', 'When is overtaking on the right allowed?', 'Thường chỉ khi các làn cùng hướng chuyển chậm / kẹt có hàng, theo luật địa phương.', 'Solo en colas lentas o carriles paralelos según normativa.', 'Typically only in slow parallel lanes / queues per local rules.', NULL),
(148, 30, 3, 1.00, 'Tín hiệu đèn đỏ tại giao lộ có nghĩa gì?', '¿Qué significa el semáforo en rojo en un cruce?', 'What does a red traffic light at a junction mean?', 'Dừng trước vạch dừng; không được đi (trừ quy định rẽ phải nơi cho phép).', 'Detenerse; no pasar salvo giro autorizado donde aplique.', 'Stop; do not proceed unless permitted turn applies.', NULL),
(149, 30, 4, 1.00, 'Khoảng cách an toàn phụ thuộc chủ yếu vào điều gì?', '¿En qué depende principalmente la distancia de seguridad?', 'What does safe following distance mainly depend on?', 'Tốc độ, điều kiện đường, mưa và phản ứng người lái.', 'Velocidad, adherencia, lluvia y tiempo de reacción.', 'Speed, grip, weather, and reaction time.', NULL),
(150, 30, 5, 1.00, 'Biển hình tròn viền đỏ nền trắng (không có gạch chéo) thường là nhóm gì?', 'Señal circular borde rojo fondo blanco sin banda: ¿grupo?', 'Circular red border white face — which sign group?', 'Thường là biển cấm (prohibición).', 'Prohibición.', 'Prohibition.', NULL);
